; Rumble sound of the enemies
; $5ea0-$5efb

; Turns the noise of SID voice 3 on while an enemy is active ($23 = $81), else off. It sets the filter cutoff $d416 from the column distance of an enemy. Without an active enemy, it calls $48e0, which lowers the cutoff to $10.
enemy_rumble_update
        lda jet_state
        and #$08
        bne enemy_rumble_done
        lda enemy_sound_on              ; $23 <> 0: the voice 3 noise is on.
        bne enemy_rumble_playing
        ldx #$03
enemy_rumble_find_loop
        lda $58,x
        beq enemy_rumble_find_next
        cmp #$d0
        bcc enemy_rumble_gate_on
enemy_rumble_find_next
        dex
        bpl enemy_rumble_find_loop
        bmi enemy_rumble_fade
enemy_rumble_gate_on
        lda #$81
        sta VCREG3
        sta enemy_sound_on
        bne enemy_rumble_set_cutoff
enemy_rumble_playing
        lda wave_launched               ; $65 = 0: no enemy of the wave has started.
        beq enemy_rumble_fade
        ldx #$03
enemy_rumble_check_loop
        lda $58,x
        beq enemy_rumble_check_next
        cmp #$d0
        bcc enemy_rumble_set_cutoff
enemy_rumble_check_next
        dex
        bpl enemy_rumble_check_loop
        lda #$80                        ; No active enemy: gate off.
        sta VCREG3
        lda #$00
        sta enemy_sound_on
        beq enemy_rumble_fade
enemy_rumble_set_cutoff
        lda map_column                  ; A = $0d + $93 - map column of the enemy, made positive.
        clc
        adc #$93
        sec
        sbc $4c,x
        bpl enemy_rumble_limit
        eor #$ff
enemy_rumble_limit
        cmp #$6d                        ; At most $6d.
        bcc enemy_rumble_store
        lda #$6d
enemy_rumble_store
        sta CUTHI
        sta filter_cutoff
        clc
        bcc enemy_rumble_done
enemy_rumble_fade
        jsr engine_cutoff_down
enemy_rumble_done
        rts
